#pragma once
#include "watchlist_workspace_model.hpp"
#include <QJsonParseError>
namespace watchlistBackup {
using namespace watchlistWorkspace;
constexpr int LIMIT=8*1024*1024;
inline void keys(QJsonObject o,QStringList wanted){auto actual=o.keys();std::sort(actual.begin(),actual.end());std::sort(wanted.begin(),wanted.end());need(actual==wanted,"备份含缺失或未知字段，未静默丢弃");}
inline void safeTree(QJsonValue v,int depth=0){need(depth<=64,"备份证据嵌套过深");if(v.isString()){auto s=v.toString();for(int i=0;i<s.size();i++){if(s[i].isHighSurrogate()){need(i+1<s.size()&&s[i+1].isLowSurrogate(),"备份Unicode无效");++i;}else need(!s[i].isLowSurrogate(),"备份Unicode无效");}need(!s.contains(QRegularExpression("(bearer\\s+|[?&](access_token|token|api_key|password|secret)=|://[^/\\s]+:[^/@\\s]+@)",QRegularExpression::CaseInsensitiveOption)),"来源证据含凭据文本，未导出");}else if(v.isArray()){for(auto x:v.toArray())safeTree(x,depth+1);}else if(v.isObject()){for(auto k:v.toObject().keys()){QString compact=k.toLower();compact.remove(QRegularExpression("[^a-z0-9]"));need(!compact.contains(QRegularExpression("(password|passwd|secret|credential|cookie|authorization|authentication|apikey|accesskey|privatekey|session|token)"))&&!QStringList{"auth","instruments","items","quote","quotes","day","minute","week","month","year","price","lastprice","bid","ask","volume"}.contains(compact),"分组证据含行情或凭据字段，未导出/导入");safeTree(k,depth+1);safeTree(v.toObject().value(k),depth+1);}}}
inline QJsonObject validateConfig(QJsonObject c){keys(c,{"schema","revision","mainIds","groups"});need(text(c,"schema")=="watchlist-workspace-config/v1","备份配置格式不支持");QJsonArray roster;for(auto id:c.value("mainIds").toArray())roster.append(QJsonObject{{"id",id},{"name",id}});auto s=c;s["schema"]="watchlist-workspace/v1";s["instruments"]=roster;validate(s);for(auto v:c.value("groups").toArray()){auto g=v.toObject();for(auto k:g.keys())need(QStringList{"groupId","name","color","readOnly","memberIds","sourceId","sourceMeta"}.contains(k),"分组未知字段需先明确备份契约，未丢弃");if(g.value("readOnly").toBool())need(g.value("sourceId").isString()&&!g.value("sourceId").toString().trimmed().isEmpty(),"只读来源组缺少sourceId证据");}safeTree(c.value("groups"));return c;}
inline QJsonObject validateBackup(QJsonObject e){keys(e,{"schema","checksumAlgorithm","sha256","config"});need(text(e,"schema")=="watchlist-workspace-backup/v1"&&text(e,"checksumAlgorithm")=="watchlist-canonical-sha256/v1"&&e.value("config").isObject(),"备份格式或校验算法不支持");auto c=validateConfig(e.value("config").toObject());need(text(e,"sha256")==hash(c),"备份校验不一致，未采用");need(QJsonDocument(e).toJson(QJsonDocument::Compact).size()<=LIMIT,"备份超过8 MiB，未截断");return e;}
inline QJsonObject exportBackup(QJsonObject s){validate(s);QJsonObject c{{"schema","watchlist-workspace-config/v1"},{"revision",s["revision"]},{"mainIds",s["mainIds"]},{"groups",s["groups"]}};validateConfig(c);return validateBackup({{"schema","watchlist-workspace-backup/v1"},{"checksumAlgorithm","watchlist-canonical-sha256/v1"},{"sha256",hash(c)},{"config",c}});}
inline QByteArray encodeBackup(QJsonObject e){validateBackup(e);return QJsonDocument(e).toJson(QJsonDocument::Compact);}
// Reject duplicate keys and non-JSON syntax before platform parsers can normalize it.
struct JsonGate {
 QString s;int i=0;
 void ws(){while(i<s.size()&&QString(" \r\n\t").contains(s[i]))++i;}
 QString string(){need(i<s.size()&&s[i]=='"',"备份JSON文本无效");int start=i++;bool done=false;while(i<s.size()){auto c=s[i++];if(c=='"'){done=true;break;}need(c.unicode()>=32,"JSON控制字符无效");if(c=='\\'){need(i<s.size(),"JSON转义缺失");auto e=s[i++];if(e=='u'){need(i+4<=s.size(),"JSON Unicode转义缺失");for(int n=0;n<4;n++)need(QRegularExpression("^[0-9a-fA-F]$").match(QString(s[i++])).hasMatch(),"JSON Unicode转义无效");}else need(QString("\"\\/bfnrt").contains(e),"JSON转义无效");}}
 need(done,"JSON文本未结束");QJsonParseError error;auto d=QJsonDocument::fromJson(("["+s.mid(start,i-start)+"]").toUtf8(),&error);need(error.error==QJsonParseError::NoError,"JSON文本无效");return d.array()[0].toString();}
 void value(int depth=0){need(depth<=64,"备份JSON嵌套过深");ws();need(i<s.size(),"JSON值缺失");auto c=s[i];if(c=='"'){string();return;}if(c=='{'||c=='['){bool object=c=='{';QSet<QString>seen;++i;ws();QChar end=object?'}':']';if(i<s.size()&&s[i]==end){++i;return;}for(;;){if(object){ws();auto k=string();need(!seen.contains(k),"JSON键重复，未采用");seen.insert(k);ws();need(i<s.size()&&s[i++]==':',"JSON冒号缺失");}value(depth+1);ws();need(i<s.size(),"JSON容器未结束");if(s[i]==end){++i;return;}need(s[i++]==',',"JSON逗号缺失");}}
 int start=i;while(i<s.size()&&!QString(" \r\n\t,]}").contains(s[i]))++i;auto token=s.mid(start,i-start);need(token=="true"||token=="false"||token=="null"||QRegularExpression("^-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?$").match(token).hasMatch(),"备份仅接受严格JSON");}
 void run(){value();ws();need(i==s.size(),"JSON尾部含多余内容");}
};
inline QJsonObject decodeBackup(QByteArray bytes){need(!bytes.isEmpty()&&bytes.size()<=LIMIT,"备份为空或超过8 MiB");QString raw=QString::fromUtf8(bytes);need(raw.toUtf8()==bytes,"备份UTF-8无效");JsonGate{raw}.run();QJsonParseError error;auto d=QJsonDocument::fromJson(bytes,&error);need(error.error==QJsonParseError::NoError&&d.isObject(),"备份JSON对象无效");return validateBackup(d.object());}
inline QJsonObject previewImport(QJsonObject e,QJsonObject base,QJsonObject current){validateBackup(e);validate(base);validate(current);auto c=e.value("config").toObject();need(equal(c.value("mainIds"),current.value("mainIds")),"备份主自选身份或顺序不匹配；请先明确协调，未丢成员");auto draft=base;draft["groups"]=c.value("groups");auto change=prepare(base,draft,current);return {{"schema","watchlist-backup-import-preview/v1"},{"backup",e},{"change",change}};}
inline QJsonObject importDraft(QJsonObject base,QJsonObject p,QJsonObject current){keys(p,{"schema","backup","change"});need(text(p,"schema")=="watchlist-backup-import-preview/v1"&&p.value("backup").isObject(),"需先预览备份差异");need(equal(p,previewImport(p.value("backup").toObject(),base,current)),"导入预览或当前配置已变化；未替换草稿");auto d=base;d["groups"]=p.value("change").toObject().value("groups");transition(base,d);return d;}
}
